-- Execute uma vez no SQL Editor do Supabase
-- GT3 Sistema — Manuais: categorias, documentos (checklists) e tabela de NRs

CREATE TABLE IF NOT EXISTS public.manuais_categorias (
  id     UUID    PRIMARY KEY DEFAULT gen_random_uuid(),
  nome   TEXT    NOT NULL,
  slug   TEXT    NOT NULL UNIQUE,
  ordem  INTEGER NOT NULL DEFAULT 0
);

CREATE TABLE IF NOT EXISTS public.manuais_documentos (
  id           TEXT        PRIMARY KEY,
  categoria_id UUID        NOT NULL REFERENCES public.manuais_categorias(id) ON DELETE CASCADE,
  titulo       TEXT        NOT NULL,
  conteudo     TEXT        NOT NULL DEFAULT '',
  secoes       JSONB       NOT NULL DEFAULT '[]',
  periodicidade TEXT       NOT NULL DEFAULT '',
  ativo        BOOLEAN     NOT NULL DEFAULT TRUE,
  created_at   TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at   TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_manuais_docs_cat   ON public.manuais_documentos(categoria_id);
CREATE INDEX IF NOT EXISTS idx_manuais_docs_ativo ON public.manuais_documentos(ativo) WHERE ativo = TRUE;

-- Trigger updated_at
CREATE OR REPLACE FUNCTION public.set_updated_at()
RETURNS TRIGGER LANGUAGE plpgsql AS $$
BEGIN
  NEW.updated_at = NOW();
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS manuais_docs_updated_at ON public.manuais_documentos;
CREATE TRIGGER manuais_docs_updated_at
  BEFORE UPDATE ON public.manuais_documentos
  FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();

-- ── RLS ──────────────────────────────────────────────────────────────────────

ALTER TABLE public.manuais_categorias  ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.manuais_documentos  ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "mc_select"        ON public.manuais_categorias;
DROP POLICY IF EXISTS "mc_insert_gestor" ON public.manuais_categorias;
DROP POLICY IF EXISTS "mc_update_gestor" ON public.manuais_categorias;
DROP POLICY IF EXISTS "mc_delete_gestor" ON public.manuais_categorias;

CREATE POLICY "mc_select"        ON public.manuais_categorias FOR SELECT TO authenticated USING (true);
CREATE POLICY "mc_insert_gestor" ON public.manuais_categorias FOR INSERT TO authenticated
  WITH CHECK (EXISTS (SELECT 1 FROM public.profiles WHERE id = auth.uid() AND papel IN ('gestor','admin')));
CREATE POLICY "mc_update_gestor" ON public.manuais_categorias FOR UPDATE TO authenticated
  USING      (EXISTS (SELECT 1 FROM public.profiles WHERE id = auth.uid() AND papel IN ('gestor','admin')));
CREATE POLICY "mc_delete_gestor" ON public.manuais_categorias FOR DELETE TO authenticated
  USING      (EXISTS (SELECT 1 FROM public.profiles WHERE id = auth.uid() AND papel IN ('gestor','admin')));

DROP POLICY IF EXISTS "md_select"        ON public.manuais_documentos;
DROP POLICY IF EXISTS "md_insert_gestor" ON public.manuais_documentos;
DROP POLICY IF EXISTS "md_update_gestor" ON public.manuais_documentos;
DROP POLICY IF EXISTS "md_delete_gestor" ON public.manuais_documentos;

CREATE POLICY "md_select"        ON public.manuais_documentos FOR SELECT TO authenticated USING (true);
CREATE POLICY "md_insert_gestor" ON public.manuais_documentos FOR INSERT TO authenticated
  WITH CHECK (EXISTS (SELECT 1 FROM public.profiles WHERE id = auth.uid() AND papel IN ('gestor','admin')));
CREATE POLICY "md_update_gestor" ON public.manuais_documentos FOR UPDATE TO authenticated
  USING      (EXISTS (SELECT 1 FROM public.profiles WHERE id = auth.uid() AND papel IN ('gestor','admin')));
CREATE POLICY "md_delete_gestor" ON public.manuais_documentos FOR DELETE TO authenticated
  USING      (EXISTS (SELECT 1 FROM public.profiles WHERE id = auth.uid() AND papel IN ('gestor','admin')));

-- ── Realtime ─────────────────────────────────────────────────────────────────

ALTER TABLE public.manuais_documentos REPLICA IDENTITY FULL;
ALTER PUBLICATION supabase_realtime ADD TABLE public.manuais_documentos;

